+  display: flex;
+  flex-direction: column;
+  min-height: 0;
+  flex: 1 1 auto;
+}
+.lab__walk-history {
+  flex: 1 1 auto;
+  min-height: 40px;
+  overflow-y: auto;
+}
 .lab__empty {
